head.b:skin:
:root {
    --bg-main: #0B0F19;
    --bg-secondary: #111827;
    --accent-primary: #00F5A0;
    --accent-secondary: #4F46E5;
    --text-main: #FFFFFF;
    --text-dim: #94A3B8;
    --glass-bg: rgba(255, 255, 255, 0.03);
    --glass-border: rgba(255, 255, 255, 0.08);
    --header-height: 80px;
    --transition-speed: 0.3s;
}

* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

body {
    background-color: var(--bg-main);
    color: var(--text-main);
    font-family: 'Inter', sans-serif;
    line-height: 1.6;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
}

#bg-canvas {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
    pointer-events: none;
}

/* Glassmorphism utility */
.glass-effect {
    background: var(--glass-bg);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--glass-border);
}

a { text-decoration: none; color: inherit; transition: var(--transition-speed); }
ul { list-style: none; }

/* Main Container */
.main-wrapper {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 20px;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
}

.content-area {
    flex: 1;
    padding-bottom: 60px;
}

/* Hero Section */
.hero-section {
    padding: 180px 20px 100px;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    position: relative;
    max-width: 1200px;
    margin: 0 auto;
}

.hero-title {
    font-size: clamp(2.8rem, 8vw, 5.5rem);
    font-weight: 800;
    margin-bottom: 35px;
    color: #FFFFFF;
    opacity: 0;
    transform: translateY(20px);
    animation: fadeIn 1s forwards 0.2s;
    line-height: 1.15;
    letter-spacing: -0.02em;
}

.hero-title .highlight {
    background: linear-gradient(90deg, #00F5A0, #00D185);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    position: relative;
    display: inline;
    filter: drop-shadow(0 0 10px rgba(0, 245, 160, 0.2));
}

.hero-description {
    font-size: 1.3rem;
    color: var(--text-dim);
    max-width: 850px;
    margin-bottom: 50px;
    opacity: 0;
    transform: translateY(20px);
    animation: fadeIn 1s forwards 0.4s;
    line-height: 1.8;
    font-weight: 400;
}

.hero-btns {
    display: flex;
    gap: 20px;
    opacity: 0;
    transform: translateY(20px);
    animation: fadeIn 1s forwards 0.6s;
}

.btn-primary, .btn-secondary {
    padding: 15px 35px;
    border-radius: 12px;
    font-weight: 700;
    font-size: 1rem;
    transition: var(--transition-speed);
}

.btn-primary {
    background: var(--accent-primary);
    color: var(--bg-main);
}

.btn-primary:hover {
    box-shadow: 0 0 30px rgba(0, 245, 160, 0.4);
    transform: translateY(-2px);
}

.btn-secondary {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    color: #fff;
    backdrop-filter: blur(10px);
}

.btn-secondary:hover {
    background: rgba(255, 255, 255, 0.1);
    border-color: #fff;
    transform: translateY(-2px);
}

@keyframes fadeIn {
    to { opacity: 1; transform: translateY(0); }
}

/* Ensure content visibility and header clearance */
.main-wrapper {
    padding-top: var(--header-height);
    transition: padding-top 0.3s ease;
}

body.is-homepage .main-wrapper {
    padding-top: 0;
}

/* Header Styles */
#mainHeader {
    height: var(--header-height);
    position: fixed;
    top: 0; left: 0; right: 0;
    z-index: 1000;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 40px;
    transition: var(--transition-speed);
}

.header-left {
    display: flex;
    align-items: center;
    gap: 20px;
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    background: linear-gradient(90deg, var(--accent-primary), var(--accent-secondary));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    text-transform: uppercase;
}

.menu-toggle {
    font-size: 1.5rem;
    color: var(--text-main);
    cursor: pointer;
    z-index: 3001;
    transition: var(--transition-speed);
}
.menu-toggle:hover { color: var(--accent-primary); }

.header-actions { display: flex; align-items: center; gap: 15px; }

.btn-icon {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    color: var(--text-main);
    width: 40px;
    height: 40px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: var(--transition-speed);
}

.btn-icon:hover {
    background: rgba(255, 255, 255, 0.1);
    border-color: var(--accent-primary);
    color: var(--accent-primary);
    box-shadow: 0 0 15px rgba(0, 245, 160, 0.2);
}

.search-btn { width: 40px; height: 40px; border-radius: 10px; }
.search-btn span { display: none; }

/* Search Modal */
#searchModal {
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(11, 15, 25, 0.95);
    backdrop-filter: blur(20px);
    z-index: 2000;
    display: none;
    align-items: flex-start;
    justify-content: center;
    padding-top: 100px;
}

.search-container {
    width: 100%;
    max-width: 700px;
    padding: 0 20px;
}

.search-input-wrapper {
    position: relative;
    margin-bottom: 30px;
}

.search-input {
    width: 100%;
    background: var(--bg-secondary);
    border: 1px solid var(--glass-border);
    border-radius: 16px;
    padding: 20px 25px;
    color: #fff;
    font-size: 1.2rem;
    outline: none;
    transition: var(--transition-speed);
}

.search-input:focus { border-color: var(--accent-primary); box-shadow: 0 0 20px rgba(0, 245, 160, 0.1); }

.search-suggestion-item {
    padding: 15px 25px;
    border-bottom: 1px solid var(--glass-border);
    cursor: pointer;
    transition: var(--transition-speed);
    color: var(--text-dim);
}

.search-suggestion-item:hover {
    background: rgba(255, 255, 255, 0.05);
    color: var(--accent-primary);
}

.search-suggestion-item i { margin-right: 15px; width: 20px; text-align: center; }

.close-search {
    position: absolute;
    top: -60px;
    right: 0;
    font-size: 1.5rem;
    color: var(--text-dim);
    cursor: pointer;
}

/* Full-screen Overlay Menu */
#sidebarMenu {
    position: fixed;
    top: 0; left: 0;
    width: 100%;
    height: 100vh;
    background: rgba(11, 15, 25, 0.95);
    backdrop-filter: blur(30px);
    z-index: 3000;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    opacity: 0;
    visibility: hidden;
    transition: 0.5s cubic-bezier(0.85, 0, 0.15, 1);
}

#sidebarMenu.active { opacity: 1; visibility: visible; }

.close-menu {
    position: absolute;
    top: 30px;
    right: 40px;
    font-size: 2rem;
    color: #fff;
    cursor: pointer;
    transition: var(--transition-speed);
}
.close-menu:hover { color: var(--accent-primary); transform: rotate(90deg); }

.nav-list { display: flex; flex-direction: column; gap: 40px; text-align: center; }
.nav-item { font-size: 2.5rem; font-weight: 800; color: #fff; display: block; transition: 0.4s; }
.nav-item:hover { color: var(--accent-primary); letter-spacing: 5px; }

.sidebar-overlay {
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0, 0, 0, 0.6);
    display: none;
    z-index: 2999;
}

/* Post Grid & Cards */
.post-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 30px;
}

.post-card {
    position: relative;
    background: var(--bg-secondary);
    border-radius: 24px;
    overflow: hidden;
    border: 1px solid var(--glass-border);
    transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.4s ease;
    display: flex;
    flex-direction: column;
    height: 100%;
}

.post-card:hover {
    transform: translateY(-10px);
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4), 0 0 20px rgba(0, 245, 160, 0.1);
    border-color: var(--accent-primary);
}

.post-card-image {
    width: 100%;
    aspect-ratio: 16/9;
    overflow: hidden;
    background: #1a2234;
}

.post-card-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: 0.6s ease;
}

.post-card:hover .post-card-image img { transform: scale(1.1); }

.post-card-content { padding: 25px; flex-grow: 1; display: flex; flex-direction: column; }

.post-card-title {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 15px;
    line-height: 1.4;
    color: #fff;
}

.post-card-snippet {
    font-size: 0.9rem;
    color: var(--text-dim);
    margin-bottom: 20px;
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.post-card-footer {
    margin-top: auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.read-more {
    color: var(--accent-primary);
    font-weight: 600;
    font-size: 0.9rem;
    display: flex;
    align-items: center;
    gap: 8px;
}

.read-more i { transition: 0.3s; }
.post-card:hover .read-more i { transform: translateX(5px); }

/* Neon effects */
.neon-glow {
    box-shadow: 0 0 10px rgba(0, 245, 160, 0.3);
}
.neon-text {
    text-shadow: 0 0 8px rgba(0, 245, 160, 0.4);
}

/* Single Post/Page Styles */
.post-single {
    max-width: 900px;
    margin: 0 auto;
}

.post-title {
    font-size: 2.5rem;
    font-weight: 800;
    margin-bottom: 30px;
    line-height: 1.2;
    color: var(--accent-primary);
}

.post-meta {
    display: flex;
    gap: 20px;
    color: var(--text-dim);
    font-size: 0.9rem;
    margin-bottom: 40px;
}

.post-body {
    font-size: 1.1rem;
    line-height: 1.8;
    color: #cbd5e1;
    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;
    overflow: visible !important;
}

.post-body img {
    max-width: 100%;
    height: auto;
    border-radius: 20px;
    margin: 30px 0;
    border: 1px solid var(--glass-border);
}

.post-body h2, .post-body h3 {
    color: #fff;
    margin: 40px 0 20px;
}

/* Footer */
footer {
    padding: 80px 20px 40px;
    text-align: center;
    border-top: 1px solid var(--glass-border);
    background: rgba(11, 15, 25, 0.5);
}

.footer-links {
    display: flex;
    justify-content: center;
    flex-wrap: wrap;
    gap: 25px;
    margin-bottom: 30px;
}

.footer-links a {
    color: var(--text-dim);
    font-size: 0.9rem;
    font-weight: 500;
}

.footer-links a:hover { color: var(--accent-primary); }

.copyright {
    color: var(--text-dim);
    font-size: 0.85rem;
    opacity: 0.7;
}

/* Legal Page Special Layout */
.legal-page {
    max-width: 800px;
    margin: 40px auto;
    text-align: center;
    min-height: 50vh;
    display: flex;
    flex-direction: column;
    justify-content: center;
}

.back-home {
    margin-top: 50px;
    display: inline-flex;
    align-items: center;
    gap: 10px;
    color: var(--accent-secondary);
    font-weight: 600;
}

/* Scroll Animations */
.reveal {
    opacity: 1;
    transform: none;
    transition: 0.8s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.js-enabled .reveal {
    opacity: 0;
    transform: translateY(30px);
}

.reveal.active {
    opacity: 1 !important;
    transform: translateY(0) !important;
}

/* Pagination */
.blog-pager {
    display: flex;
    justify-content: center;
    gap: 20px;
    margin-top: 60px;
}
.blog-pager a {
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    padding: 12px 25px;
    border-radius: 12px;
    color: var(--text-main);
    font-weight: 600;
    font-size: 0.9rem;
}
.blog-pager a:hover {
    border-color: var(--accent-primary);
    color: var(--accent-primary);
    box-shadow: 0 0 20px rgba(0, 245, 160, 0.1);
}

body.script:
//
    (function() {
        const canvas = document.getElementById('bg-canvas');
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true });

        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));

        const particlesCount = 300; // Fewer particles for better line performance
        const positions = new Float32Array(particlesCount * 3);
        const colors = new Float32Array(particlesCount * 3);
        const velocities = new Float32Array(particlesCount * 3);

        const color1 = new THREE.Color('#00F5A0');
        const color2 = new THREE.Color('#4F46E5');

        for(let i = 0; i < particlesCount * 3; i += 3) {
            positions[i] = (Math.random() - 0.5) * 10;
            positions[i+1] = (Math.random() - 0.5) * 10;
            positions[i+2] = (Math.random() - 0.5) * 10;

            velocities[i] = (Math.random() - 0.5) * 0.01;
            velocities[i+1] = (Math.random() - 0.5) * 0.01;
            velocities[i+2] = (Math.random() - 0.5) * 0.01;

            const mixedColor = color1.clone().lerp(color2, Math.random());
            colors[i] = mixedColor.r;
            colors[i+1] = mixedColor.g;
            colors[i+2] = mixedColor.b;
        }

        const geometry = new THREE.BufferGeometry();
        geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

        const material = new THREE.PointsMaterial({
            size: 0.03,
            vertexColors: true,
            transparent: true,
            opacity: 0.8,
            blending: THREE.AdditiveBlending
        });

        const points = new THREE.Points(geometry, material);
        scene.add(points);

        // Neural Connections
        const lineGeometry = new THREE.BufferGeometry();
        const lineMaterial = new THREE.LineBasicMaterial({ color: 0x00F5A0, transparent: true, opacity: 0.2 });
        const lines = new THREE.LineSegments(lineGeometry, lineMaterial);
        scene.add(lines);

        // Data Streams
        const streamsCount = 50;
        const streamPositions = new Float32Array(streamsCount * 3);
        for(let i = 0; i < streamsCount * 3; i += 3) {
            streamPositions[i] = (Math.random() - 0.5) * 10;
            streamPositions[i+1] = Math.random() * 10;
            streamPositions[i+2] = (Math.random() - 0.5) * 10;
        }
        const streamGeometry = new THREE.BufferGeometry();
        streamGeometry.setAttribute('position', new THREE.BufferAttribute(streamPositions, 3));
        const streamMaterial = new THREE.PointsMaterial({ size: 0.05, color: 0x4F46E5, transparent: true, opacity: 0.5 });
        const streams = new THREE.Points(streamGeometry, streamMaterial);
        scene.add(streams);

        camera.position.z = 3;

        let mouseX = 0;
        let mouseY = 0;

        document.addEventListener('mousemove', (event) => {
            mouseX = (event.clientX / window.innerWidth) - 0.5;
            mouseY = (event.clientY / window.innerHeight) - 0.5;
        });

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        function animate() {
            requestAnimationFrame(animate);

            // Move particles
            const posArray = points.geometry.attributes.position.array;
            const linePositions = [];
            for(let i = 0; i < particlesCount * 3; i += 3) {
                posArray[i] += velocities[i];
                posArray[i+1] += velocities[i+1];
                posArray[i+2] += velocities[i+2];

                if (Math.abs(posArray[i]) > 5) velocities[i] *= -1;
                if (Math.abs(posArray[i+1]) > 5) velocities[i+1] *= -1;
                if (Math.abs(posArray[i+2]) > 5) velocities[i+2] *= -1;

                // Connection logic
                for(let j = i + 3; j < particlesCount * 3; j += 3) {
                    const dx = posArray[i] - posArray[j];
                    const dy = posArray[i+1] - posArray[j+1];
                    const dz = posArray[i+2] - posArray[j+2];
                    const dist = Math.sqrt(dx*dx + dy*dy + dz*dz);
                    if (dist < 1.5) {
                        linePositions.push(posArray[i], posArray[i+1], posArray[i+2]);
                        linePositions.push(posArray[j], posArray[j+1], posArray[j+2]);
                    }
                }
            }
            points.geometry.attributes.position.needsUpdate = true;

            lineGeometry.setAttribute('position', new THREE.Float32BufferAttribute(linePositions, 3));

            // Move streams
            const streamArray = streams.geometry.attributes.position.array;
            for(let i = 0; i < streamsCount * 3; i += 3) {
                streamArray[i+1] -= 0.05;
                if (streamArray[i+1] < -5) streamArray[i+1] = 5;
            }
            streams.geometry.attributes.position.needsUpdate = true;

            points.rotation.y += 0.001;
            points.position.x += (mouseX * 0.5 - points.position.x) * 0.05;
            points.position.y += (-mouseY * 0.5 - points.position.y) * 0.05;

            renderer.render(scene, camera);
        }
        animate();
    })();

// Add class to body if homepage
if (window.location.pathname === "/" || window.location.pathname === "/index.html") {
    document.body.classList.add('is-homepage');
}
document.body.classList.add('js-enabled');

    function toggleSearch(show) {
        const modal = document.getElementById('searchModal');
        modal.style.display = show ? 'flex' : 'none';
        if (show) {
            const input = document.querySelector('.search-input');
            input.focus();
            document.body.style.overflow = 'hidden';
            initAutocomplete(input);
        } else {
            document.body.style.overflow = 'auto';
        }
    }

    function initAutocomplete(input) {
        const suggestions = [
            { text: 'AI Tools', label: 'Tools', icon: 'fas fa-tools' },
            { text: 'Learn AI', label: 'Learn', icon: 'fas fa-graduation-cap' },
            { text: 'AI Monetization', label: 'Monetization', icon: 'fas fa-dollar-sign' },
            { text: 'AI Image Prompts', label: 'Prompts', icon: 'fas fa-terminal' }
        ];

        const suggestionBox = document.getElementById('searchSuggestions');

        input.addEventListener('input', (e) => {
            const val = e.target.value.toLowerCase();
            suggestionBox.innerHTML = '';

            if (val.length > 1) {
                const filtered = suggestions.filter(s => s.text.toLowerCase().includes(val));
                filtered.forEach(s => {
                    const div = document.createElement('div');
                    div.className = 'search-suggestion-item';
                    div.innerHTML = `<i class='${s.icon}'></i> ${s.text}`;
                    div.onclick = () => {
                        window.location.href = '/search/label/' + s.label;
                    };
                    suggestionBox.appendChild(div);
                });
            }
        });
    }

    function toggleMenu(show) {
        const sidebar = document.getElementById('sidebarMenu');
        const overlay = document.getElementById('sidebarOverlay');
        if (show) {
            sidebar.classList.add('active');
            overlay.style.display = 'block';
            document.body.style.overflow = 'hidden';
        } else {
            sidebar.classList.remove('active');
            overlay.style.display = 'none';
            document.body.style.overflow = 'auto';
        }
    }

    // 3D Tilt Effect
    function initTilt() {
        const cards = document.querySelectorAll('.post-card');
        cards.forEach(card => {
            card.addEventListener('mousemove', e => {
                const rect = card.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;
                const centerX = rect.width / 2;
                const centerY = rect.height / 2;
                const rotateX = (y - centerY) / 20;
                const rotateY = (centerX - x) / 20;

                card.style.transform = `perspective(1000px) translateY(-10px) rotateX(${rotateX}deg) rotateY(${rotateY}deg)`;
            });

            card.addEventListener('mouseleave', () => {
                card.style.transform = 'perspective(1000px) translateY(0) rotateX(0) rotateY(0)';
            });
        });
    }
    document.addEventListener('DOMContentLoaded', initTilt);

    // Reading Time Calculation
    function calculateReadingTime() {
        const bodies = document.querySelectorAll('.post-body');
        bodies.forEach(body => {
            const text = body.innerText;
            const wordsPerMinute = 200;
            const words = text.split(/\s+/).length;
            const minutes = Math.ceil(words / wordsPerMinute);
            const display = body.closest('article').querySelector('.reading-time-dynamic');
            if (display) display.innerHTML = `<i class='far fa-clock'></i> ${minutes} min read`;
        });
    }
    document.addEventListener('DOMContentLoaded', calculateReadingTime);

    // Scroll Reveal
    function initReveal() {
        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('active');
                }
            });
        }, { threshold: 0.05, rootMargin: '0px 0px -50px 0px' });

        const elements = document.querySelectorAll('.post-card, .post-single, .reveal');
        elements.forEach(el => {
            observer.observe(el);
        });
    }
    document.addEventListener('DOMContentLoaded', initReveal);

    function dynamicReset() {
        // Reset Search UI
        const searchInput = document.querySelector('.search-input');
        if (searchInput) searchInput.value = '';
        toggleSearch(false);

        // Re-reveal cards with a slight delay for effect
        const cards = document.querySelectorAll('.post-card');
        cards.forEach(card => {
            card.classList.remove('active');
            setTimeout(() => card.classList.add('active'), 100);
        });

        console.log('UI State Reset Dynamically');
    }
//
